// 查找字符的位图数据
static inline const uint8_t* findChineseBitmap(const char* utf8Char) {
    for (int i = 0; i < 250; i++) {
        if (strcmp(HUIWEN_FANGSONG_CHARS[i].utf8, utf8Char) == 0) {
            return HUIWEN_FANGSONG_CHARS[i].bitmap;
        }
    }
    return nullptr;
}

